import{SYMBOLS,LINES,LINE_COLORS,REELS,PRIZE_TIERS,FREE_MODES,chooseFreeMode,playSpin,collectPick,seeded}from'./engine.js';
const $=id=>document.getElementById(id),fmt=n=>Math.round(n).toLocaleString('en-US'),money=n=>`$${(n*.05).toFixed(2)} virtual`,wait=ms=>new Promise(r=>setTimeout(r,ms));
const STORE='pixel-palace-v1',LINE_OPTIONS=[1,5,10,15,20];
const initialGrid=[[0,3,7],[1,0,4],[6,0,8],[2,5,0],[3,1,2]];
let storageOK=true;
function load(){let saved;try{saved=JSON.parse(localStorage.getItem(STORE)||'null');}catch{storageOK=false;}
 const s={version:1,balance:2000,lines:20,coins:1,lastWin:0,grid:initialGrid.map(c=>[...c]),free:null,bonus:null,notice:null,lastWins:[],spins:0,settings:{muted:false,volume:55,reduced:matchMedia('(prefers-reduced-motion: reduce)').matches,fast:false}};
 if(!saved||saved.version!==1)return s;
 if(Number.isSafeInteger(saved.balance)&&saved.balance>=0)s.balance=saved.balance;
 if(LINE_OPTIONS.includes(saved.lines))s.lines=saved.lines;if(Number.isInteger(saved.coins)&&saved.coins>=1&&saved.coins<=5)s.coins=saved.coins;
 if(Array.isArray(saved.grid)&&saved.grid.length===5&&saved.grid.every(c=>Array.isArray(c)&&c.length===3&&c.every(n=>Number.isInteger(n)&&n>=0&&n<SYMBOLS.length)))s.grid=saved.grid;
 if(Number.isSafeInteger(saved.lastWin)&&saved.lastWin>=0)s.lastWin=saved.lastWin;
 if(saved.settings){s.settings={muted:!!saved.settings.muted,volume:Number.isFinite(saved.settings.volume)?Math.max(0,Math.min(100,saved.settings.volume)):55,reduced:!!saved.settings.reduced,fast:!!saved.settings.fast};}
 const f=saved.free;if(f&&Number.isInteger(f.remaining)&&f.remaining>=0&&LINE_OPTIONS.includes(f.lines)&&Number.isInteger(f.coins)&&f.coins>=1&&f.coins<=5&&Number.isSafeInteger(f.total)&&f.total>=0&&Array.isArray(f.locked)){s.free={...f,locked:f.locked.filter(p=>Array.isArray(p)&&p.length===2&&Number.isInteger(p[0])&&p[0]>=0&&p[0]<5&&Number.isInteger(p[1])&&p[1]>=0&&p[1]<3)};}
 const b=saved.bonus;if(b?.kind==='match3'&&Array.isArray(b.tiles)&&b.tiles.length===9&&b.tiles.every(t=>Number.isInteger(t)&&t>=0&&t<4)&&Array.isArray(b.chosen)&&b.chosen.every(i=>Number.isInteger(i)&&i>=0&&i<9)&&new Set(b.chosen).size===b.chosen.length&&Number.isSafeInteger(b.bet)&&b.bet>0){s.bonus={...b,matches:[0,0,0,0]};for(const i of b.chosen)s.bonus.matches[b.tiles[i]]++;s.bonus.won=s.bonus.matches.some(n=>n>=3);s.bonus.total=s.bonus.won?PRIZE_TIERS[s.bonus.matches.findIndex(n=>n>=3)].times*b.bet:0;}
 if(b&&Array.isArray(b.values)&&b.values.length===9&&b.values.every(n=>Number.isSafeInteger(n)&&n>0)&&Array.isArray(b.chosen)&&b.chosen.length<=3&&b.chosen.every(n=>Number.isInteger(n)&&n>=0&&n<9)&&new Set(b.chosen).size===b.chosen.length){s.bonus={...b,total:b.chosen.reduce((t,i)=>t+b.values[i],0)};}
 if(saved.notice&&['free','retrigger'].includes(saved.notice.type)&&Number.isInteger(saved.notice.count))s.notice=saved.notice;
 s.spins=Number.isSafeInteger(saved.spins)?saved.spins:0;return s;
}
let phase='idle',reelAnimations=[],stopRequested=false,skipCount=false,presentingBalance=null,visualWin=0;
let state=load(),busy=false,inGame=false,freePaused=true,freeTimer=null,lineTimer=null,toastTimer=null,featureAction=null,showAll=false,winAnimation=null;
function save(){try{localStorage.setItem(STORE,JSON.stringify(state));}catch{storageOK=false;}$('storageNotice').hidden=storageOK;}
function iconStyle(id){const s=SYMBOLS[id];return id<6?`background-image:url(assets/${s.id}.webp);background-size:contain;background-position:center;background-repeat:no-repeat;mix-blend-mode:normal`: `background-position:${s.pos[0]*50}% ${s.pos[1]*50}%`;}
function symbolHTML(id,c,r){const s=SYMBOLS[id];return`<div class="cell ${id>5?'special':'character'}" data-c="${c}" data-r="${r}" data-symbol="${id}" style="--symbol-color:${s.color}" aria-label="Reel ${c+1}, row ${r+1}: ${s.name}"><div class="symbol-art symbol-${s.id}" style="${iconStyle(id)}"></div><span class="symbol-name">${s.name}</span></div>`;}
function renderReel(c,grid=state.grid){const reel=$('reels').children[c];reel.innerHTML=`<div class="reel-track">${grid[c].map((id,r)=>symbolHTML(id,c,r)).join('')}</div>`;}
function renderGrid(){if(!$('reels').children.length)$('reels').innerHTML=Array.from({length:5},(_,c)=>`<div class="reel" data-reel="${c}"></div>`).join('');for(let c=0;c<5;c++)renderReel(c);}
function activeLines(){return state.free?.lines||state.lines;}function activeCoins(){return state.free?.coins||state.coins;}
function renderStats(){
 const lines=activeLines(),coins=activeCoins(),bet=lines*coins,shownBalance=presentingBalance??state.balance;
 for(const id of ['balance','headerBalance'])$(id).textContent=fmt(shownBalance);$('balanceMoney').textContent=money(shownBalance);$('headerDollars').textContent=money(shownBalance);
 $('lineCount').textContent=lines;$('coinCount').textContent=coins;$('totalBet').textContent=bet;$('betMoney').textContent=state.free?'FREE SPIN':money(bet);$('lastWin').textContent=fmt(busy?visualWin:state.lastWin);$('winMoney').textContent=money(busy?visualWin:state.lastWin);
 const locked=busy||!!state.free||!!state.bonus;
 $('lessLines').disabled=locked||state.lines===1;$('moreLines').disabled=locked||state.lines===20;$('lessCoins').disabled=locked||state.coins===1;$('moreCoins').disabled=locked||state.coins===5;$('maxBet').disabled=locked;
 $('spin').disabled=busy?!['reels','wins'].includes(phase)||stopRequested:!!state.bonus||!!state.notice||!!state.free&&state.free.remaining===0;
 $('spin').classList.toggle('free-spin',!!state.free);
 $('spin').firstElementChild.textContent=busy?(phase==='reels'?'STOP':phase==='wins'?'COLLECT':'WAIT'):state.free?'FREE SPIN':'SPIN';$('spin').lastElementChild.textContent=busy?(phase==='reels'?'QUICK STOP':phase==='wins'?'SKIP COUNT-UP':'FEATURE IN PLAY'):state.free?(freePaused?'PRESS TO RESUME':'PLAYING FREE GAMES'):'PRESS SPACE';
 $('backLobby').disabled=busy;$('refill').disabled=busy;
 $('freeBar').hidden=!state.free;if(state.free){$('freeCount').textContent=`${state.free.remaining} LEFT`;$('freeModeName').textContent=state.free.mode?`${state.free.mode.toUpperCase()} • ${state.free.multiplier}× WINS`:'FREE SPINS';$('featureWin').textContent=fmt(state.free.total);$('pauseFree').textContent=freePaused?'Resume':'Pause';}
 document.querySelectorAll('.line-rail span').forEach(el=>el.classList.toggle('inactive',Number(el.dataset.line)>=lines));
 $('fastButton').textContent=`Quick spin: ${state.settings.fast?'on':'off'}`;$('fastButton').setAttribute('aria-pressed',String(state.settings.fast));
 $('soundButton').textContent=state.settings.muted?'♪̸':'♫';$('soundButton').setAttribute('aria-label',state.settings.muted?'Unmute sound':'Mute sound');$('soundButton').title=state.settings.muted?'Sound off':'Sound on';
 document.body.classList.toggle('reduced',state.settings.reduced);$('volume').value=state.settings.volume;$('reduceMotion').checked=state.settings.reduced;
 $('sessionNote').textContent=state.free?'Power-up feature active':'Fixed prizes · Scale with bet';$('machine').classList.toggle('in-free-games',!!state.free);$('prizeBank').innerHTML=[...PRIZE_TIERS].reverse().map(t=>`<div style="--tier:${t.color}"><span>${t.name}</span><strong>${fmt(t.times*bet)}</strong><small>CREDITS</small></div>`).join('');
}
function message(text,detail){$('gameMessage').textContent=text;if(detail!==undefined)$('winDetail').textContent=detail;}
function toast(text){clearTimeout(toastTimer);$('toast').textContent=text;$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,3500);}
let ctx,master;
function audioReady(){try{if(!ctx){ctx=new(window.AudioContext||window.webkitAudioContext)();master=ctx.createGain();master.connect(ctx.destination);}if(ctx.state==='suspended')ctx.resume().catch(()=>{});master.gain.value=state.settings.muted?0:state.settings.volume/100*.25;}catch{}}
function tone(freq,duration=.1,delay=0,type='sine',gain=.3,to=null){if(!ctx||state.settings.muted||document.hidden)return;try{const start=ctx.currentTime+delay,o=ctx.createOscillator(),g=ctx.createGain();o.type=type;o.frequency.setValueAtTime(freq,start);if(to)o.frequency.exponentialRampToValueAtTime(to,start+duration);g.gain.setValueAtTime(.0001,start);g.gain.exponentialRampToValueAtTime(gain,start+.006);g.gain.exponentialRampToValueAtTime(.0001,start+duration);o.connect(g);g.connect(master);o.start(start);o.stop(start+duration+.02);o.onended=()=>{o.disconnect();g.disconnect();};}catch{}}
function sound(kind){audioReady();if(kind==='spin'){tone(100,.3,0,'triangle',.6,45);[440,554,659].forEach((f,i)=>tone(f,.12,i*.055,'triangle',.2));}else if(kind==='stop'){tone(85,.13,0,'triangle',.7,40);tone(660,.055,.01,'sine',.12);}else if(kind==='click')tone(720,.055,0,'sine',.2);else if(kind==='bonus'){[392,494,587,784,988,1175,1568].forEach((f,i)=>tone(f,.27,i*.11,'triangle',.3));}else if(kind==='wild'){[260,390,520,780,1040].forEach((f,i)=>tone(f,.17,i*.065,'sawtooth',.13));}else if(kind==='win'){[523,659,784,1046].forEach((f,i)=>tone(f,.25,i*.12,'triangle',.24));}else if(kind==='pick'){tone(1200,.4,0,'sine',.25,600);tone(800,.3,.08,'triangle',.22);}}
function clearLines(){clearInterval(lineTimer);lineTimer=null;$('paylines').innerHTML='';$('paylines').classList.remove('all-lines');document.querySelectorAll('.cell.winning,.line-rail .lit').forEach(e=>e.classList.remove('winning','lit'));}
function lineSVG(index,count=5){const rows=LINES[index],color=LINE_COLORS[index%10],points=rows.slice(0,count).map((r,c)=>`${100+c*200},${100+r*200}`).join(' ');return`<polyline points="${points}" stroke="${color}"/>`+(count<5?`<circle cx="${100+(count-1)*200}" cy="${100+rows[count-1]*200}" r="8" fill="${color}"/>`:'');}
function highlightWin(w){$('paylines').innerHTML=lineSVG(w.line,w.count);document.querySelectorAll('.cell.winning,.line-rail .lit').forEach(e=>e.classList.remove('winning','lit'));for(let c=0;c<w.count;c++)document.querySelector(`.cell[data-c="${c}"][data-r="${w.rows[c]}"]`)?.classList.add('winning');document.querySelectorAll(`[data-line="${w.line}"]`).forEach(e=>e.classList.add('lit'));$('winDetail').textContent=`LINE ${w.line+1} · ${w.count} ${SYMBOLS[w.symbol].name.toUpperCase()} · ${fmt(w.amount)} CREDITS`;}
function showWins(wins){clearLines();if(!wins?.length)return;let index=0;highlightWin(wins[0]);if(wins.length>1)lineTimer=setInterval(()=>{index=(index+1)%wins.length;highlightWin(wins[index]);},1400);}
function allLines(){clearLines();showAll=!showAll;$('linesButton').textContent=showAll?'Hide lines':'View lines';if(showAll){$('paylines').classList.add('all-lines');$('paylines').innerHTML=LINES.slice(0,activeLines()).map((_,i)=>lineSVG(i)).join('');message(`${activeLines()} active paylines. Wins start on the leftmost reel.`,'PAYLINE MAP');}else{message('Choose your bet. Press SPIN to play.',`${activeLines()} ACTIVE LINES`);}}
function coinsEffect(big=false){if(state.settings.reduced)return;const box=$('particles');box.innerHTML='';const rng=seeded(Date.now());for(let i=0;i<(big?55:20);i++){const p=document.createElement('i');p.className='coin-particle';p.style.left=`${rng()*100}%`;p.style.setProperty('--duration',`${1.7+rng()*1.4}s`);p.style.setProperty('--delay',`${rng()*.8}s`);box.append(p);}setTimeout(()=>box.replaceChildren(),4200);}
function startReelSound(){
 if(!ctx||state.settings.muted)return()=>{};
 try{const buffer=ctx.createBuffer(1,ctx.sampleRate,ctx.sampleRate),data=buffer.getChannelData(0),rng=seeded(Date.now());let brown=0;for(let i=0;i<data.length;i++){brown=(brown+(rng()*2-1)*.02)/1.02;data[i]=brown*3.5;}const source=ctx.createBufferSource(),filter=ctx.createBiquadFilter(),gain=ctx.createGain();source.buffer=buffer;source.loop=true;filter.type='lowpass';filter.frequency.value=1350;gain.gain.setValueAtTime(0,ctx.currentTime);gain.gain.linearRampToValueAtTime(.30,ctx.currentTime+.12);source.connect(filter);filter.connect(gain);gain.connect(master);source.start();return()=>{gain.gain.cancelScheduledValues(ctx.currentTime);gain.gain.setTargetAtTime(.0001,ctx.currentTime,.06);source.stop(ctx.currentTime+.3);source.onended=()=>{source.disconnect();filter.disconnect();gain.disconnect();};};}catch{return()=>{};}
}
async function countWin(amount,bet){
 if(!amount)return;phase='wins';skipCount=false;stopRequested=false;const big=amount>=bet*20;
 const duration=state.settings.reduced?0:state.settings.fast?350:big?Math.min(5500,1800+amount/2):amount<=bet?450:1200;
 if(big){$('bigWinTitle').textContent=amount>=bet*100?'MEGA WIN!':amount>=bet*50?'SUPER WIN!':'BIG WIN!';$('bigWin').hidden=false;coinsEffect(true);}renderStats();
 const start=performance.now();let lastTick=0;$('lastWin').closest('.meter').classList.add('counting');
 await new Promise(resolve=>{const frame=now=>{const progress=skipCount||!duration?1:Math.min(1,(now-start)/duration);visualWin=Math.round(amount*(1-Math.pow(1-progress,2)));$('lastWin').textContent=fmt(visualWin);$('winMoney').textContent=money(visualWin);$('bigWinAmount').textContent=fmt(visualWin);if(now-lastTick>95&&progress<1&&amount>bet){tone(880+(Math.floor(progress*12)%4)*110,.06,0,'sine',.10);lastTick=now;}if(progress<1)winAnimation=requestAnimationFrame(frame);else resolve();};frame(start);});
 $('lastWin').closest('.meter').classList.remove('counting');if(big&&!skipCount)await wait(state.settings.fast?250:750);$('bigWin').hidden=true;
}
async function animateReels(before){
 const reduced=state.settings.reduced,quick=state.settings.fast;let seenFree=0,seenBonus=0,anticipationFrom=-1;
 for(let c=0;c<4;c++){seenFree+=before[c].includes(7);seenBonus+=before[c].includes(8);if(seenFree===2||seenBonus===2){anticipationFrom=c+1;break;}}
 const stopMotor=startReelSound();reelAnimations=[];stopRequested=false;
 try{await Promise.all(Array.from($('reels').children).map(async(reel,c)=>{
  const track=reel.firstElementChild,current=Array.from(track.children).map(el=>Number(el.dataset.symbol));
  const rng=seeded(Date.now()+c*87),filler=Array.from({length:21+c*3},()=>REELS[c][Math.floor(rng()*REELS[c].length)]),symbols=[...before[c],...filler,...(current.length===3&&current.every(Number.isFinite)?current:[0,1,2])];
  track.innerHTML=symbols.map((id,i)=>symbolHTML(id,c,i%3)).join('');reel.classList.add('spinning');
  const height=reel.clientHeight/3,distance=(symbols.length-3)*height;
  const anticipation=anticipationFrom>=0&&c>=anticipationFrom&&!quick&&!reduced;
  const duration=reduced?80+c*30:quick?480+c*120:1450+c*270+(anticipation?(c-anticipationFrom+1)*600:0);
  if(reduced||!track.animate)await wait(duration);else{
   const anim=track.animate([{transform:`translateY(${-distance}px)`,offset:0,easing:'cubic-bezier(.45,0,.75,1)'},{transform:`translateY(${-distance*.84}px)`,offset:.20,easing:'linear'},{transform:`translateY(${-height*4}px)`,offset:.72,easing:'cubic-bezier(.12,.55,.16,1)'},{transform:'translateY(0)',offset:1}],{duration,fill:'forwards'});
   reelAnimations.push(anim);await anim.finished.catch(()=>{});anim.cancel();
  }
  reel.classList.remove('spinning');renderReel(c,before);reel.classList.add('landing');sound('stop');setTimeout(()=>reel.classList.remove('landing'),230);
  for(const cell of reel.querySelectorAll('.cell.special'))if(Number(cell.dataset.symbol)>6){cell.classList.add('scatter-land');tone(700+c*130,.2,0,'triangle',.2);}
  if(c===anticipationFrom-1&&!quick&&!reduced&&!stopRequested){$('reelStage').classList.add('anticipating');message('One more bonus symbol…','BONUS ANTICIPATION');for(let j=c+1;j<5;j++)$('reels').children[j].classList.add('anticipating-reel');tone(440,.6,0,'triangle',.10,880);}
 }));}finally{stopMotor();reelAnimations=[];$('reelStage').classList.remove('anticipating');document.querySelectorAll('.anticipating-reel').forEach(e=>e.classList.remove('anticipating-reel'));}
}
async function animateWild(result){if(!result.wildCells.length)return;message(`${result.wildKind}! Watch the wilds land…`,'POWER-UP ACTIVATED');$('takeover').querySelector('b').textContent=result.wildKind;$('takeover').hidden=false;sound('wild');await wait(state.settings.reduced?150:700);$('takeover').hidden=true;
 for(const[c,r]of result.wildCells){const cell=document.querySelector(`.cell[data-c="${c}"][data-r="${r}"]`);if(cell){
  if(!state.settings.reduced){const stage=$('reelStage'),box=stage.getBoundingClientRect(),target=cell.getBoundingClientRect(),star=document.createElement('div');star.className='wild-projectile';star.style.cssText=iconStyle(6);stage.append(star);const x=target.left-box.left+target.width/2-32,y=target.top-box.top+target.height/2-32,startX=box.width/2-32,startY=box.height/2-32;const flight=star.animate([{transform:`translate(${startX}px,${startY}px) scale(1.6) rotate(-35deg)`,opacity:0},{transform:`translate(${(startX+x)/2}px,${Math.min(startY,y)-45}px) scale(1.3) rotate(25deg)`,opacity:1,offset:.45},{transform:`translate(${x}px,${y}px) scale(1) rotate(0)`,opacity:1}],{duration:state.settings.fast?180:300,easing:'ease-out',fill:'forwards'});await flight.finished.catch(()=>{});star.remove();}
  cell.outerHTML=symbolHTML(6,c,r);const newCell=document.querySelector(`.cell[data-c="${c}"][data-r="${r}"]`);newCell.classList.add('new-wild');tone(750+c*90,.18,0,'triangle',.2);}await wait(state.settings.reduced?0:state.settings.fast?30:65);}await wait(state.settings.reduced?0:350);
}
async function spin(){
 if(!inGame||document.querySelector('dialog[open]'))return;
 if(busy){if(phase==='reels'&&!stopRequested){stopRequested=true;reelAnimations.forEach((a,i)=>setTimeout(()=>{try{a.finish();}catch{}},i*45));renderStats();}else if(phase==='wins')skipCount=true;return;}
 if(state.bonus||state.notice||state.free?.remaining===0){continueFeatures();return;}
 if(state.free){freePaused=false;clearTimeout(freeTimer);}audioReady();clearLines();showAll=false;$('linesButton').textContent='View lines';
 let result;const oldBalance=state.balance;try{result=playSpin(state);}catch(e){toast(e.message);if(state.balance<state.lines*state.coins)openSettings();return;}
 busy=true;phase='reels';stopRequested=false;visualWin=0;presentingBalance=oldBalance-(result.wasFree?0:result.bet);save();renderStats();$('balance').textContent=fmt(oldBalance-(result.wasFree?0:result.bet));$('balanceMoney').textContent=money(oldBalance-(result.wasFree?0:result.bet));$('lastWin').textContent='0';$('winMoney').textContent=money(0);
 message(result.wasFree?'Power-up free spin…':'Good luck! Reels are rolling.',result.wasFree?'FREE SPIN':`${result.lines} ACTIVE LINES`);sound('spin');
 try{
  await animateReels(result.before);phase='feature';renderStats();await animateWild(result);renderGrid();
  if(result.payout){if(result.payout>result.bet)sound('win');else tone(660,.15,0,'sine',.15);showWins(result.wins);message(`${fmt(result.payout)} credits${result.wins.length?` · ${result.wins.length} winning ${result.wins.length===1?'line':'lines'}`:''}${result.scatterPay?` · ${fmt(result.scatterPay)} scatter credits`:''}${result.multiplier>1?` · ${result.multiplier}× line wins`:''}`);await countWin(result.payout,result.bet);}
  else message(result.bonus?'The treasure room is opening…':result.freeAward?'Power-up! Free spins unlocked.':'No winning line this time. Ready for another spin?',`${activeLines()} ACTIVE LINES`);
  if(result.freeAward||result.bonus){phase='feature';renderStats();clearLines();document.querySelectorAll('.cell').forEach(cell=>{if((result.freeAward&&cell.dataset.symbol==='7')||(result.bonus&&cell.dataset.symbol==='8'))cell.classList.add('triggered');});message(result.bonus?'TREASURE BONUS! Match three to reveal your prize.':'FREE GAMES! Choose your power-up.','FEATURE AWARDED');sound('bonus');await wait(state.settings.reduced?0:1100);}
 }catch(e){console.error('Animation interrupted',e);renderGrid();toast('Spin completed. Your credits have been saved.');}
 finally{busy=false;phase='idle';presentingBalance=null;stopRequested=false;$('takeover').hidden=true;$('bigWin').hidden=true;renderStats();continueFeatures();}
}
function openDialog(id){pauseAuto();if(!$(id).open)$(id).showModal();}
function pauseAuto(){clearTimeout(freeTimer);freePaused=true;renderStats();}
function scheduleFree(){clearTimeout(freeTimer);if(!inGame||freePaused||busy||document.hidden||document.querySelector('dialog[open]')||!state.free||state.free.remaining<=0)return;freeTimer=setTimeout(spin,state.settings.fast?800:1600);}
function featureModal({title,eyebrow,text,symbol=7,button='LET’S PLAY',onContinue}){clearTimeout(freeTimer);$('featureTitle').textContent=title;$('featureEyebrow').textContent=eyebrow;$('featureText').textContent=text;$('featureArt').style.cssText=iconStyle(symbol);$('featureContinue').textContent=button;featureAction=onContinue;$('featureDialog').showModal();sound('bonus');}
function continueFeatures(){
 if(!inGame||busy||document.querySelector('dialog[open]'))return;
 if(state.bonus){renderBonus();$('bonusDialog').showModal();sound('bonus');return;}
 if(state.free?.choice){renderFreeOptions();$('freeChoiceDialog').showModal();sound('bonus');return;}
 if(state.notice){const n=state.notice;featureModal({title:`${n.count} ${n.type==='retrigger'?'MORE ':''}FREE SPINS`,eyebrow:n.type==='retrigger'?'POWER-UP RETRIGGERED':'POWER-UP BONUS',text:state.free?.mode?`Keep your ${state.free.multiplier}× line-win multiplier for these extra games. Your bet stays locked.`:'Your saved feature continues with its original sticky-wild rules and locked bet.',button:n.type==='retrigger'?'KEEP PLAYING':'START FREE SPINS',onContinue:()=>{state.notice=null;save();freePaused=false;renderStats();scheduleFree();}});return;}
 if(state.free?.remaining===0){const total=state.free.total;featureModal({title:`${fmt(total)} CREDITS`,eyebrow:'FREE SPINS COMPLETE',text:`You played ${state.free.played} free spins and won ${money(total).replace(' virtual','')} in virtual credits. All winnings have been added to your balance.`,symbol:6,button:'BACK TO THE REELS',onContinue:()=>{state.free=null;freePaused=true;save();renderStats();message('Free spins complete. Ready when you are.',`${state.lines} ACTIVE LINES`);}});if(total>0)coinsEffect(true);return;}
 scheduleFree();
}
function renderFreeOptions(){const budget=state.free?.budget||12;$('freeOptions').innerHTML=FREE_MODES.map((m,i)=>`<button data-free-mode="${m.id}" class="free-option mode-${m.id}"><div class="choice-character" style="${iconStyle([0,3,2][i])}"></div><span>${m.name}</span><strong>${budget/m.multiplier}</strong><b>FREE GAMES</b><div class="multiplier-badge">${m.multiplier}× LINE WINS</div><small>${m.description}</small><em>SELECT</em></button>`).join('');}
function renderBonus(){
 const b=state.bonus;if(!b)return;const modern=b.kind==='match3',done=modern?b.won:b.chosen.length>=3;
 $('bonusTitle').textContent=modern?'Match three. Reveal your prize.':'Choose your treasure.';$('matchMeters').hidden=!modern;
 if(modern)$('matchMeters').innerHTML=PRIZE_TIERS.map((t,i)=>`<div class="match-meter ${b.matches[i]===3?'matched':''}" style="--tier:${t.color}"><strong>${t.name}</strong><span>${fmt(t.times*b.bet)}</span><div>${[0,1,2].map(j=>`<i class="${j<b.matches[i]?'filled':''}"></i>`).join('')}</div></div>`).join('');
 $('treasureGrid').innerHTML=(modern?b.tiles:b.values).map((v,i)=>{const picked=b.chosen.includes(i),tier=modern?PRIZE_TIERS[v]:null;return`<button class="chest ${picked?'picked':''} ${modern&&picked?'prize-reveal':''}" data-pick="${i}" ${picked||done?'disabled':''} ${tier?`style="--tier:${tier.color}"`:''} aria-label="${picked?'Chest '+(i+1)+', '+(modern?tier.name:v+' credits'):'Choose treasure chest '+(i+1)}">${picked?(modern?`<span class="prize-medal">✦</span><strong>${tier.name}</strong><small>${fmt(tier.times*b.bet)} CREDITS</small>`:`<strong>${fmt(v)}</strong><small>CREDITS</small>`):`<div class="table-symbol" style="${iconStyle(8)}"></div><span>${i+1}</span>`}</button>`;}).join('');
 $('bonusTotal').textContent=fmt(b.total);$('pickStatus').textContent=done?(modern?`${PRIZE_TIERS[b.winner].name} PRIZE! ${fmt(b.total)} credits added to your balance.`:'Your treasure has been added to your balance.'):modern?'Keep picking until you reveal 3 matching prize symbols.':`${3-b.chosen.length} picks remaining. Every chest is a winner.`;$('collectBonus').hidden=!done;
}
function chooseChest(index){const b=state.bonus;if(!b||b.chosen.includes(index)||(b.kind==='match3'?b.won:b.chosen.length>=3))return;const amount=collectPick(state,index);save();renderBonus();renderStats();sound('pick');if(amount&&b.kind==='match3'){sound('bonus');coinsEffect(true);}else if(b.kind==='match3'&&b.matches[b.tiles[index]]===2){tone(988,.3,0,'triangle',.2);}}
function enter(){inGame=true;location.hash='machine';$('lobby').hidden=true;$('game').hidden=false;audioReady();renderGrid();renderStats();window.scrollTo(0,0);if(state.free&&!state.notice&&!state.bonus&&state.free.remaining>0){freePaused=true;message('Your free spins are saved. Press FREE SPIN to resume.','FEATURE IN PROGRESS');}continueFeatures();}
function lobby(){if(busy){toast('Let this spin finish first.');return;}pauseAuto();clearLines();inGame=false;location.hash='lobby';$('game').hidden=true;$('lobby').hidden=false;window.scrollTo(0,0);}
function changeBet(type,delta){if(busy||state.free||state.bonus)return;clearLines();showAll=false;$('linesButton').textContent='View lines';if(type==='lines')state.lines=LINE_OPTIONS[Math.max(0,Math.min(4,LINE_OPTIONS.indexOf(state.lines)+delta))];else state.coins=Math.max(1,Math.min(5,state.coins+delta));save();renderStats();message('Choose your bet. Press SPIN to play.',`${state.lines} ACTIVE LINES`);sound('click');}
function rules(){return`<div class="rules-cards"><div class="rules-card"><div class="table-symbol" style="${iconStyle(7)}"></div><strong>POWER-UP FREE SPINS</strong><p>3+ controller reels unlock a choice of free games and a 1×, 2×, or 3× line-win multiplier.</p></div><div class="rules-card"><div class="table-symbol" style="${iconStyle(8)}"></div><strong>MATCH-THREE PRIZE PICK</strong><p>Chests on 3+ reels unlock a MINI, MINOR, MAJOR, or GRAND prize reveal.</p></div><div class="rules-card"><div class="table-symbol" style="${iconStyle(6)}"></div><strong>WILD TAKEOVER</strong><p>Random wild throws, full-reel wilds, and rare mega takeovers.</p></div></div><h3>Every line is another way to win</h3><p>Choose <strong>1, 5, 10, 15, or 20 active lines</strong>, then <strong>1–5 credits per line</strong>. One credit is a virtual nickel. Total bet = lines × credits per line. For example, 20 lines × 1 credit = 20 credits ($1.00 virtual).</p><ul><li>Match <strong>3, 4, or 5 symbols</strong> consecutively from the leftmost reel along an active payline. Only the highest paying combination on each line pays; wins on different lines are added together.</li><li><strong>Wild stars</strong> substitute for all six character symbols, and pay their own combination when it is worth more. Wilds do not substitute for controllers or chests.</li><li><strong>Controllers and chests count anywhere</strong> on separate reels, regardless of active lines. Both features can trigger on the same spin. The treasure game plays first.</li><li>Free games use your triggering line bet at no cost. With 3 controllers choose <strong>12 games at 1×, 6 at 2×, or 4 at 3×</strong> line wins. With 4 controllers the choices are 18 / 9 / 6; with 5 they are 24 / 12 / 8. During free games 3+ controllers add 6 / 3 / 2 games for the chosen mode. Wild throwouts are more frequent in free games; wilds reset for each new game. Unfinished features from the first version retain their sticky-wild rules.</li><li>In the treasure bonus, <strong>keep picking until 3 prize symbols match</strong>. MINI pays 5×, MINOR 10×, MAJOR 50×, and GRAND 250× your triggering total bet. These are fixed prizes, not progressives. The award tier is randomly determined when the bonus opens and its hidden tiles are shuffled; your picks reveal it. The full prize is credited when the third match appears. Three, four, or five controller reels also pay a scatter award of 2×, 5×, or 10× the total bet. Scatter awards do not receive the free-game multiplier.</li><li>MAX BET selects 20 lines × 5 credits = 100 credits ($5.00 virtual); it does not start a spin. Space starts a spin; press STOP to finish the reel animation early. COLLECT skips a win count-up without changing the award. Free spins play automatically after you start the feature; Pause stops after the current spin.</li></ul><h3>Character payouts</h3><p>Amounts below are credits for a 1-credit line bet. Multiply by your credits per line.</p><table class="paytable"><thead><tr><th>SYMBOL</th><th>3</th><th>4</th><th>5</th></tr></thead><tbody>${SYMBOLS.slice(0,7).map((s,i)=>`<tr><td><div class="table-symbol" style="${iconStyle(i)}"></div><span>${s.name}<small>${s.series||'Substitutes for character symbols'}</small></span></td>${s.pay.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table><h3>The 20 paylines</h3><p>Your first ${activeLines()} ${activeLines()===1?'line is':'lines are'} active. Lines are numbered in the order shown.</p><div class="line-grid">${LINES.map((rows,i)=>`<div class="line-thumbnail ${i>=activeLines()?'disabled':''}"><span>${i+1}</span><svg viewBox="0 0 100 60">${Array.from({length:15},(_,j)=>`<circle cx="${10+Math.floor(j/3)*20}" cy="${10+j%3*20}" r="2" fill="#54455f"/>`).join('')}<polyline points="${rows.map((r,c)=>`${10+c*20},${10+r*20}`).join(' ')}" stroke="${LINE_COLORS[i%10]}"/></svg></div>`).join('')}</div><p class="quiet">Virtual play only. No purchases, cash prizes, cash-out, or real-money wagering. This is an independent fan-made arcade prototype. Character artwork is from the official <a href="https://www.smashbros.com/en_US/fighter/index.html" target="_blank" rel="noopener">Super Smash Bros. Ultimate</a> and <a href="https://marvelvscapcominfinite.com/characters/spencer/index.html" target="_blank" rel="noopener">Marvel vs. Capcom: Infinite</a> character pages. All characters and artwork belong to their respective owners. Every spin is random and is not adjusted based on your balance or past wins.</p>`;}
function openInfo(){if(busy)return;$('infoContent').innerHTML=rules();openDialog('infoDialog');}
function openSettings(){openDialog('settingsDialog');}
$('enterMachine').onclick=()=>{sound('click');enter();};$('backLobby').onclick=lobby;document.querySelector('.brand').onclick=e=>{e.preventDefault();lobby();};$('spin').onclick=spin;
$('lessLines').onclick=()=>changeBet('lines',-1);$('moreLines').onclick=()=>changeBet('lines',1);$('lessCoins').onclick=()=>changeBet('coins',-1);$('moreCoins').onclick=()=>changeBet('coins',1);
$('maxBet').onclick=()=>{if(busy||state.free||state.bonus)return;state.lines=20;state.coins=5;showAll=false;$('linesButton').textContent='View lines';save();renderStats();clearLines();sound('click');message('Maximum bet selected: 100 credits ($5.00 virtual).','20 ACTIVE LINES');};
$('linesButton').onclick=()=>{if(!busy)allLines();};$('paytableButton').onclick=openInfo;$('lobbyHow').onclick=openInfo;$('settingsButton').onclick=openSettings;
$('soundButton').onclick=()=>{state.settings.muted=!state.settings.muted;save();renderStats();audioReady();if(!state.settings.muted)sound('click');};
$('volume').oninput=e=>{state.settings.volume=Number(e.target.value);state.settings.muted=false;save();audioReady();renderStats();};$('volume').onchange=()=>sound('click');
$('reduceMotion').onchange=e=>{state.settings.reduced=e.target.checked;save();renderStats();};
$('fastButton').onclick=()=>{state.settings.fast=!state.settings.fast;save();renderStats();sound('click');};
$('refill').onclick=()=>{if(busy)return;state.balance+=2000;save();renderStats();sound('win');toast('2,000 complimentary credits added. Have fun!');};
$('fullscreenButton').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('Fullscreen isn’t available here. Try your browser’s fullscreen option.');}};
document.addEventListener('fullscreenchange',()=>{$('fullscreenButton').setAttribute('aria-label',document.fullscreenElement?'Exit fullscreen':'Enter fullscreen');});
$('pauseFree').onclick=()=>{freePaused=!freePaused;if(freePaused)clearTimeout(freeTimer);else scheduleFree();renderStats();};
$('freeOptions').onclick=e=>{const button=e.target.closest('[data-free-mode]');if(button&&chooseFreeMode(state,button.dataset.freeMode)){save();$('freeChoiceDialog').close();freePaused=false;renderStats();sound('bonus');scheduleFree();}};
$('skipWin').onclick=()=>{skipCount=true;};
$('featureContinue').onclick=()=>{const action=featureAction;featureAction=null;$('featureDialog').close();if(action)action();};
$('treasureGrid').onclick=e=>{const b=e.target.closest('[data-pick]');if(b)chooseChest(Number(b.dataset.pick));};
$('collectBonus').onclick=()=>{if(!state.bonus||(state.bonus.kind==='match3'?!state.bonus.won:state.bonus.chosen.length<3))return;state.bonus=null;save();$('bonusDialog').close();renderStats();continueFeatures();};
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());
for(const id of ['infoDialog','settingsDialog'])$(id).addEventListener('close',()=>{renderStats();continueFeatures();});
for(const id of ['featureDialog','bonusDialog','freeChoiceDialog'])$(id).addEventListener('cancel',e=>e.preventDefault());
document.addEventListener('keydown',e=>{if(e.code==='Space'&&!e.repeat&&inGame&&!document.querySelector('dialog[open]')&&!['INPUT','TEXTAREA','SELECT','BUTTON','A'].includes(e.target.tagName)){e.preventDefault();spin();}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){pauseAuto();if(master)master.gain.value=0;}else audioReady();});
window.addEventListener('pagehide',()=>save());
for(const side of ['leftRail','rightRail'])$(side).innerHTML=Array.from({length:10},(_,i)=>{const n=i+(side==='rightRail'?10:0);return`<span data-line="${n}" style="--line-color:${LINE_COLORS[n%10]}">${n+1}</span>`;}).join('');
$('lobbyReels').innerHTML=[0,6,3,1,0,2,8,5,7].map(id=>`<div class="mini-symbol" style="${iconStyle(id)}"></div>`).join('');
renderGrid();renderStats();save();
if(location.hash==='#machine'||state.free||state.bonus)enter();
